<?php $request = Illuminate\Http\Request::create("/api/v1/devices", "POST", ["customer_id" => 1, "emi_account_id" => null, "display_name" => "", "brand" => "Samsung", "model" => "", "manufacturer" => "Samsung", "serial_number" => "", "imei" => "", "imei2" => "", "invoice_number" => "INV-20260924-1234", "notes" => ""]); $request->headers->set("X-Company-Id", "1"); $request->headers->set("Accept", "application/json"); $user = App\Models\User::find(2); if(!$user) $user = App\Models\User::first(); $request->setUserResolver(function () use ($user) { return $user; }); $response = app(Illuminate\Contracts\Http\Kernel::class)->handle($request); echo $response->getStatusCode() . "\n"; echo $response->getContent();
